export type ShanyuanRecipient = "target" | "self";

export interface ShanyuanOutcome {
	recipient: ShanyuanRecipient;
	gainYuan: boolean;
}

export interface XiongAnfaState {
	sex: "female" | "unknown";
	skills: string[];
	yuan: number;
	ku: number;
}

export const MAX_YUAN = 3;

export function getShanyuanAiScore(yuan: number, attitude: number): number {
	const count = normalizedMarkCount(yuan);
	if (attitude > 0) return [8, 6, 4, 2][Math.min(count, 3)];
	return count === 0 ? 5 : -10;
}

export function getLiyeRecipientAiValue(yuan: number, attitude: number): number {
	const draw = getLiyeDrawCount(yuan);
	return attitude > 0 ? draw * (1 + Math.min(5, attitude) / 10) : -draw;
}

export function getLiyeAiValue(relatedPlayerCount: number, bestRecipientValue: number): number {
	return getLiyeSelfDrawCount(relatedPlayerCount) + bestRecipientValue;
}

function normalizedMarkCount(value: number): number {
	return Math.max(0, Math.trunc(value));
}

export function getShanyuanOutcome(color: string, currentYuan = 0): ShanyuanOutcome {
	const gainYuan = normalizedMarkCount(currentYuan) < MAX_YUAN;
	return color === "red" ? { recipient: "target", gainYuan } : { recipient: "self", gainYuan };
}

export function getLiyeSelfDrawCount(relatedPlayerCount: number): number {
	return normalizedMarkCount(relatedPlayerCount);
}

export function getLiyeDrawCount(yuan: number): number {
	return Math.min(MAX_YUAN, normalizedMarkCount(yuan));
}

export function getLiyeDiscardCount(handcardCount: number): number {
	return Math.min(2, normalizedMarkCount(handcardCount));
}

export function getYihuanDrawCount(yuan: number): number {
	return normalizedMarkCount(yuan);
}

export function getYihuanPrepDrawCount(ku: number): number {
	return normalizedMarkCount(ku) > 0 ? 1 : 0;
}

export function getYihuanRescueKuCost(ku: number): number {
	return normalizedMarkCount(ku);
}

export function isAnfaJudgment(suit: string, number: number): boolean {
	return suit === "club" && number >= 2 && number <= 9;
}

export function shouldRunAnfaCheck(change: "gain" | "remove", hasOccurred: boolean, sex = "female"): boolean {
	return change === "gain" && !hasOccurred && sex === "female";
}

export function canUseKuRescue(ku: number, hp: number): boolean {
	return normalizedMarkCount(ku) > 0 && hp < 1;
}

export function getKuRescueRecovery(hp: number): number {
	return Math.max(0, 1 - Math.trunc(hp));
}

export function applyAnfaTransition(state: XiongAnfaState): XiongAnfaState {
	const skills = state.skills.filter(skill => !["q_xiong_shanyuan", "q_xiong_liye"].includes(skill));
	if (!skills.includes("q_xiong_yihuan")) {
		skills.push("q_xiong_yihuan");
	}
	return {
		sex: "unknown",
		skills,
		yuan: state.yuan,
		ku: state.ku,
	};
}
